            None,
            None,
            None,
            &[],
            &HashMap::new(),
        );
        assert!(args.last().unwrap().contains("cd '/tmp/a b; rm -rf /'"));
        assert!(args.last().unwrap().contains("exec 'pi' '--mode' 'rpc'"));
    }
