            vec!["sh".into(), "-c".into(), script.into()],
            "test",
            None,
            None,
            Duration::from_secs(1),
            Some(callback),
        )
        .await
        .unwrap();
        let turn = session.prompt("hello").await.unwrap();
        assert_eq!(turn.text, "done");
        assert!(!turn.failed);
